query Query(
  $sourceProductionHistorySerial: [String!]!, 
  $destinationProductionHistorySerial: [String!]!
) {
  destinationProductionHistoryInputs: productionHistoryInput(
    where: {
      serial: {
        _in: $destinationProductionHistorySerial
      }
    }
  ){
    edges {
      node {
        id
        serial
        quantity
        productionHistoryId
        productionHistory{
          id
          quantity
          serial
        }

      }
    }
  }
  sourceProductionHistory: productionHistory(where: {
     serial:  {
        _in: $sourceProductionHistorySerial
     }}){
    edges {
      node {
        id
				serial
        quantity
        productionHistoryInputs{
          edges{
            node{
              id
              quantity
              productionHistoryId
              serial
            }
          }
        }
      }
    }
  }
}

data.transform:
(
  $nodes := $state.context.nodes;
  $link := [
    $nodes.(
      $crr := $;

      $forwardNodes := nextNodes.{
        "from": $crr.serial,
        "to": serial,
        "value": $crr.quantity
      };

      $backwardNodes := sourceNodes.{
        "from": serial,
        "to": $crr.serial,
        "value": quantity
      };

      [$backwardNodes, $forwardNodes]
    )
  ];

  {
    "nodes": $nodes.{"label": serial},
    "links":  $uniqBy( $link, function($v){ $v.from & ":" & $v.to } )
  }
)

(

  $pickNode := $pick(?, ["serial", "quantity"]);
  $pickSerial := $lookup(?, "serial");
  $contextNodes := $state.context.nodes;

  /*Get all the nodes from the query that are not already in context */
  $currentNodes := $uniqBy(
    [$.*.edges.node.( $omit($, ["id", "productionHistoryId", "productionHistory", "productionHistoryInputs"]))] , 
    $pickSerial
  ) ~> $filter(function($v){ $not($v.serial in $state.context.nodes.serial)}); 

  /* Get all the nodes that are inputs to the upstream nodes*/
  $sourceNodes := sourceProductionHistory.edges.node.productionHistoryInputs.edges.node.( 
    $omit($, ["id", "productionHistoryId"])
  );

  /*Get all the downstream nodes*/
  $nextNodes := destinationProductionHistoryInputs.edges.node.productionHistory.($omit($, "id"));

  $nodes := $values(

    {
      /* Add links to the nodes that are made from these nodes */
      "sourceNodes": $sourceNodes? $sourceNodes~>|$|( 
        $sourceNode := $;
        { 
          "nextNodes": $uniqBy(
            [
              $currentNode.$pickNode($),
              $$.sourceProductionHistory.edges.node[$sourceNode.serial in  productionHistoryInputs.edges.node.serial].$pickNode($)
            ],
            $pickSerial
          ) 
        }
      ) |,
      /* Add links to these nodes for the for things that are made up of this node or things that made this node  */
      "currentNode": $currentNodes? $currentNodes~>|$| { "sourceNodes": [$sourceNodes.$pickNode($)], "nextNodes": [$nextNodes.$pickNode($)] } |,
      /* Add links to these nodes that for the nodes that make up this node */
      "nextNodes": $nextNodes? $nextNodes~>|$| (
        $nextNode := $;
        {
          "sourceNodes": $uniqBy(
            [
              $currentNodes.$pickNode($),
              $$.destinationProductionHistoryInputs.edges.node[$nextNode.serial in  productionHistory.serial].$pickNode($)
            ],
            $pickSerial
          ) 
        }
      ) |
    }

)~>$flatten(?, 2);

/*fill in the links for the most upstream node in context*/
$upStreamNode := $contextNodes[$isNilOrEmpty(sourceNodes)]~>|$|(
    $currUpStreamNode := $;
    { "sourceNodes": [$nodes[$currUpStreamNode.serial in nextNodes].$pickNode($)]}
  )|;

/*fill in the links for the most downstream node in context*/
$downStreamNode := $contextNodes[$isNilOrEmpty(nextNodes)]~>|$|(
    $currDownStreamNode := $;
    { "nextNodes": [$nodes[$currDownStreamNode.serial in sourceNodes].$pickNode($)]}
  )|;

$newNodes := [ 
      $contextNodes[ $not(serial  in [ $downStreamNode.serial, $upStreamNode.serial ] ) ],
      $upStreamNode,
      $downStreamNode,
      $nodes
    ];

  $state.context~>|$| {"nodes": $newNodes} |
)

